package com.ruoyi.medical.persistence;
import com.ruoyi.medical.persistence.mapper.*;
import javax.sql.DataSource;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.*;
/** Explicit N01 model lane. Missing production storage/model/tokenizer dependencies fail
 * startup rather than silently constructing mocks or enabling the unrelated TASK adapter. */
@Configuration
@ConditionalOnProperty(name="medical.professional-runtime.plan-draft-enabled",havingValue="true",matchIfMissing=false)
public class TaskPlanDraftInvocationConfiguration {
 @Bean(name="planDraftInvocationHttpSchema") TaskInvocationHttpSchema planDraftInvocationHttpSchema(FormalInvocationSchema schema)throws Exception{return new TaskInvocationHttpSchema(schema);}
 @Bean TaskPlanDraftInvocationContextOrchestrator taskPlanDraftInvocationContextOrchestrator(TaskPlanDraftSupervisor supervisors,TaskPlanDraftInvocationContext contexts,FormalInvocationSourceOriginals originals,TaskPlanDraftPackages packages,FormalTokenizerRunner tokenizer,TaskPlanDraftInvocationObjects objects,@Qualifier("formalInvocationObjectTransport")RuntimeObjectTransport transport,TaskPlanDraftInvocationRecords records,TaskPlanDraftInvocationService invocations){return new TaskPlanDraftInvocationContextOrchestrator(supervisors,contexts,originals,packages,tokenizer,objects,transport,records,invocations);}
 @Bean(name="planDraftInvocationLocalBridge") TaskInvocationLocalBridge planDraftInvocationLocalBridge(org.springframework.core.env.Environment e){String p="medical.professional-runtime.plan-draft-gateway.";return new TaskInvocationLocalBridge(new TaskInvocationLocalBridge.Configuration(java.nio.file.Path.of(e.getRequiredProperty(p+"executable")),e.getRequiredProperty(p+"executable-sha256"),java.nio.file.Path.of(e.getRequiredProperty(p+"entrypoint")),e.getRequiredProperty(p+"entrypoint-sha256"),java.nio.file.Path.of(e.getRequiredProperty(p+"package-root")),java.nio.file.Path.of(e.getRequiredProperty(p+"package-manifest")),e.getRequiredProperty(p+"package-manifest-sha256"),java.nio.file.Path.of(e.getRequiredProperty(p+"private-configuration")),java.time.Duration.ofSeconds(Long.parseLong(e.getRequiredProperty(p+"timeout-seconds")))));}
 @Bean TaskPlanDraftInvocationBridge taskPlanDraftInvocationBridge(TaskPlanDraftInvocationContextOrchestrator contexts,TaskPlanDraftInvocationService service,@Qualifier("planDraftInvocationLocalBridge")TaskInvocationLocalBridge bridge,org.springframework.core.env.Environment e)throws Exception{return new TaskPlanDraftInvocationBridge(contexts,service,bridge,java.time.Duration.ofSeconds(Long.parseLong(e.getRequiredProperty("medical.professional-runtime.plan-draft-model-token-lifetime-seconds"))));}
 @Bean TaskPlanDraftInvocationSchema taskPlanDraftInvocationSchema()throws Exception{return new TaskPlanDraftInvocationSchema();}
 @Bean TaskPlanDraftPackages taskPlanDraftPackages(ArtifactRegistryMapper artifacts,SourceReadMapper sources,DependencyLineage lineage,ArtifactSourceAuthority authority,AgentPublicationDependencies governance,EvaluationReferences profiles,EvaluationDependencyPolicy policy,SourceUploadTransport transport){return new TaskPlanDraftPackages(artifacts,sources,lineage,authority,governance,profiles,policy,transport);}
 @Bean TaskPlanDraftPromptCompiler taskPlanDraftPromptCompiler(FormalCapabilityIdentityAuthority capabilities,PermissionSchema json)throws Exception{return new TaskPlanDraftPromptCompiler(capabilities,json);}
 @Bean TaskPlanDraftInvocationObjects taskPlanDraftInvocationObjects(DataSource data,PermissionSchema json,FormalInvocationSchema schema,TaskPlanDraftInvocationSchema exact,DependencyManifestSchema manifests){return new TaskPlanDraftInvocationObjects(data,json,schema,exact,manifests);}
 @Bean TaskPlanDraftInvocationRecords taskPlanDraftInvocationRecords(DataSource data,TaskPlanDraftInvocationObjects objects,FormalInvocationSchema schema,PermissionSchema json,TaskPlanDraftProducerAuthority producers){return new TaskPlanDraftInvocationRecords(data,objects,schema,json,producers);}
 @Bean TaskPlanDraftInvocationContext taskPlanDraftInvocationContext(DataSource data,ModelConfigurationService models,ModelEligibilityAuthority eligibility,ResourceReadAuthority resources,SourceReadAuthority sources,TaskPlanDraftPackages packages,FormalInvocationSourceOriginals originals,FormalInvocationSchema schema,TaskPlanDraftInvocationSchema exact,PermissionSchema json,TaskPlanDraftContentAuthority contents,@Qualifier("formalInvocationObjectTransport")RuntimeObjectTransport transport,TaskPlanDraftProducerAuthority producers){return new TaskPlanDraftInvocationContext(data,models,eligibility,resources,sources,packages,originals,schema,exact,json,contents,transport,producers);}
 @Bean TaskPlanDraftInvocationService taskPlanDraftInvocationService(DataSource data,TaskPlanDraftWorkerAccess workers,RunTokenAuthority tokens,TaskPlanDraftInvocationContext contexts,TaskPlanDraftInvocationRecords records,FormalInvocationReservations reservations,FormalInvocationDispatch dispatch,FormalInvocationReceiptObjects receipts,FormalInvocationSettlement settlement,FormalInvocationObjectRegistration objects,FormalProviderCaptureEvidence captures,FormalInvocationSchema schema)throws Exception{return new TaskPlanDraftInvocationService(data,workers,tokens,contexts,records,reservations,dispatch,receipts,settlement,objects,new TaskInvocationResults(data,null,settlement,objects,captures,schema),schema);}
}
